import express from "express";
const app = express();
app.use(express.json({ limit: "10kb" }));
app.get("/hello/:name", (req, res) => res.send(`Hi, ${req.params.name}!`));
app.listen(3000, "127.0.0.1");

import express from "express";
const app = express();
app.use(express.json({ limit: "10kb" }));
app.get("/search", (req, res) => res.json({ term: typeof req.query.q === "string" ? req.query.q : "" }));
app.listen(3000, "127.0.0.1");

import express from "express";
const app = express();
app.use(express.json({ limit: "10kb" }));
app.post("/books", (req, res) => {
 if (typeof req.body?.title !== "string") return res.status(400).json({ error: "Title needed" });
 return res.status(201).json({ title: req.body.title });
});
app.listen(3000, "127.0.0.1");

import express from "express";
const app = express();
app.use(express.json({ limit: "10kb" }));
app.get("/double/:n", (req, res) => {
 const n = Number(req.params.n);
 if (!Number.isSafeInteger(n)) return res.status(400).send("Use a whole number");
 return res.json({ answer: n * 2 });
});
app.listen(3000, "127.0.0.1");

import express from "express";
const app = express();
app.use(express.json({ limit: "10kb" }));
app.use((req, res, next) => { res.locals.school = "Oak School"; next(); });
app.get("/", (req, res) => res.send(res.locals.school));
app.listen(3000, "127.0.0.1");

