import express from "express";
const app = express();
app.use(express.json({ limit: "10kb" }));
app.get("/broken", (req, res) => { throw new Error("Practice failure"); });
app.use((err, req, res, next) => res.status(500).json({ error: "Try again later" }));
app.listen(3000, "127.0.0.1");

